import base64

# Read full certificate
with open('new_dist_cert.p12', 'rb') as f:
    cert_data = f.read()
    cert_b64 = base64.b64encode(cert_data).decode()

# The profile b64 provided by user earlier
profile_b64 = ''

with open('COPY_THESE_TO_GITHUB.txt', 'w') as f:
    f.write("=== BUILD_CERTIFICATE_BASE64 ===\n")
    f.write(cert_b64)
    f.write("\n\n=== BUILD_PROVISION_PROFILE_BASE64 ===\n")
    f.write(profile_b64)
    f.write("\n\n=== P12_PASSWORD ===\n")
    f.write("123456")

print("Fixed the file CONTENT. Please re-open COPY_THESE_TO_GITHUB.txt now.")
